"""Build the small, crawlable studio website. Python 3 + Pillow."""
import os, json, shutil, html, re
from urllib.parse import urlparse
from pathlib import Path
from legal import PAGES
from PIL import Image
import io

ROOT=Path(__file__).parent
OUT=ROOT/'dist'
ORIGIN=os.environ.get('SITE_URL','https://patrickscoloringpages.site').rstrip('/')
BASE_PATH=urlparse(ORIGIN).path.rstrip('/')
DATA=json.loads((ROOT/'content.json').read_text())
if OUT.exists(): shutil.rmtree(OUT)
(OUT/'assets').mkdir(parents=True)
for p in (ROOT/'assets').iterdir(): shutil.copy2(p,OUT/'assets'/p.name)
shutil.copy2(ROOT/'style.css',OUT/'assets/style.css')
e=html.escape
brand="Patrick’s Little Studio"
pages=[]
def image(d,large=False):
    s=d['slug']; return f'<img src="/assets/{s}-{"large" if large else "small"}.webp?v=20261023-collection-v4" width="{1200 if large else 480}" height="{1200 if large else 480}" alt="{e(d["alt"])}" loading="{"eager" if large else "lazy"}" decoding="async">'
def cards(items):
    return '<div class="grid">'+''.join(f'<a class="card" href="/coloring-pages/{d["slug"]}/">{image(d)}<span class="card-label">{e(d["name"])} <span aria-hidden="true">↗</span></span><span class="card-note">{e(d["short"])}</span></a>' for d in items)+'</div>'
def page(path,title,desc,body,schema=None,noindex=False):
    url=ORIGIN+path
    base=[{'@context':'https://schema.org','@type':'WebSite','name':brand,'url':ORIGIN+'/'}, {'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':url}]
    if schema:base+=schema
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}"><link rel="canonical" href="{e(url)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css?v=20261011-print"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{e(url)}"><meta property="og:image" content="{ORIGIN}/assets/octopus-mandala-large.webp"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">{json.dumps(base,ensure_ascii=False).replace('<','\\u003c')}</script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><a class="brand" href="/" aria-label="Patrick’s Little Studio home"><img src="/assets/flower.svg" width="44" height="44" alt=""><span>Patrick’s<br><strong>Little Studio</strong></span></a><nav aria-label="Main navigation"><a href="/coloring-pages/">The mandalas</a><a href="/about/">Meet the studio</a></nav></header><main id="main">{body}</main><footer><div class="footer-top"><a class="footer-brand" href="/">Patrick’s Little Studio</a><p>A little paper. A little color. A little time to play.</p></div><div class="footer-links"><a href="/coloring-pages/">All mandalas</a><a href="/about/">About & creative process</a><a href="/terms/">Printing & use</a><a href="/privacy/">Privacy</a><a href="/cookies/">Cookies</a><a href="/legal/">Legal notice</a></div><small>© 2026 Patrick’s Little Studio · Free for personal and classroom coloring.</small></footer></body></html>'''
    dest=OUT/('404.html' if path=='/404/' else path.lstrip('/')+'index.html')
    doc=re.sub(r'(href|src)="/(?!/)',lambda m:m.group(1)+'="'+BASE_PATH+'/',doc)
    dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(doc)
    if not noindex:pages.append(path)

for d in DATA:
    s=d['slug']
    for label,size in [('small',480),('large',1200)]:
        im=Image.open(ROOT/'originals'/f'{s}.png').convert('RGB');im.thumbnail((size,size));im.save(OUT/'assets'/f'{s}-{label}.webp',quality=90)
    shutil.copy2(ROOT/'originals'/f'{s}.png',OUT/'assets'/f'{s}-print.png')

page('/',"Free Mandalas for Kids | Patrick’s Little Studio",'Seven easy printable mandalas for kids: friendly animals, a woodland cottage, and sun and moon. Choose a design and print it directly from your browser on A4 or Letter paper.',f'''<section class="hero"><div><p class="eyebrow">WELCOME TO MY LITTLE STUDIO</p><h1>Big imagination.<br>Little moments<br>of <em>color.</em></h1><p class="intro">Free printable mandalas for kids, filled with friendly faces and simple shapes. Pick a favorite, grab your pencils, and make it yours.</p><a class="button" href="#collection">Find your mandala <span aria-hidden="true">↓</span></a><p class="quiet">Seven designs. Free printing. No sign-up.</p></div><div class="hero-art">{image(DATA[0],True)}<span class="scribble">Your colors go here ↗</span></div></section><section id="collection"><div class="section-heading"><div><p class="eyebrow">THE FIRST LITTLE COLLECTION</p><h2>Easy mandalas to print & color</h2></div><p>Simple shapes, roomy spaces,<br>and a character in every circle.</p></div>{cards(DATA)}</section><section class="studio"><img src="/assets/patrick.webp" width="600" height="600" alt="Portrait of the Patrick studio character at a drawing desk" loading="lazy"><div><p class="eyebrow">A LITTLE SPACE FOR CREATIVITY</p><h2>Hello from<br>the little studio.</h2><p>Welcome to a small collection with a simple idea: give children a friendly picture, a few repeating shapes, and room to choose their own colors. Start with a favorite animal or a little woodland home, and turn a blank circle into something personal.</p><a class="text-link" href="/about/">Explore the story of the studio ↗</a></div></section><section class="print-guide"><p class="eyebrow">FROM SCREEN TO PAPER</p><h2>Ready in three little steps.</h2><ol><li><strong>Pick a circle.</strong><span>Open any design to see the full drawing.</span></li><li><strong>Print a page.</strong><span>Tap Print this mandala, then choose your printer and paper size.</span></li><li><strong>Make it yours.</strong><span>Use crayons, pencils, or markers. There is no right palette.</span></li></ol><p>Every design is free for home and classroom coloring. <a href="/terms/">Read the simple use guidelines.</a></p></section>''')
page('/coloring-pages/','Easy Printable Mandalas for Kids | The Collection', 'Browse seven simple mandala coloring pages for kids, with large geometric spaces and free browser printing on A4 or US Letter paper.',f'''<section class="page-heading"><p class="eyebrow">SEVEN LITTLE WORLDS</p><h1>Printable mandalas<br>for curious kids.</h1><p class="intro">Animals, a woodland home, and a smiling sky. Each circular design combines a clear central picture with repeating geometric shapes. These easy pages are intended for children who prefer larger coloring spaces.</p></section>{cards(DATA)}<section class="prose"><h2>Which mandala should you choose?</h2><p>Start with the butterfly or bee for broad, simple sections. The cottage offers windows and a little path, while the turtle adds a few smaller shell sections. Choose the drawing that interests your child rather than an exact age label.</p><h2>Printing your mandala</h2><p>Open a design and tap Print this mandala. Choose A4 or US Letter paper, portrait orientation, and Fit to page in your print settings. Turn off browser headers and footers. The drawing uses 90% of the available width with extra white margins, so borderless printing is unnecessary. For markers, use suitable paper and protect the table underneath.</p></section>''')
for i,d in enumerate(DATA):
    s=d['slug'];path=f'/coloring-pages/{s}/'
    related=[DATA[x] for x in d['related']]
    breadcrumbs={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'},{'@type':'ListItem','position':2,'name':'Mandalas','item':ORIGIN+'/coloring-pages/'},{'@type':'ListItem','position':3,'name':d['name'],'item':ORIGIN+path}]}
    img_schema={'@context':'https://schema.org','@type':'ImageObject','name':d['name'],'description':d['alt'],'contentUrl':ORIGIN+f'/assets/{s}-large.webp','acquireLicensePage':ORIGIN+'/terms/','license':ORIGIN+'/terms/','creditText':brand,'creator':{'@type':'Organization','name':brand}}
    page(path,d['seo']+' | Patrick’s Little Studio',d['description'],f'''<nav class="crumbs" aria-label="Breadcrumb"><a href="/">Home</a> / <a href="/coloring-pages/">Mandalas</a> / <span>{e(d['name'])}</span></nav><section class="detail"><div class="drawing">{image(d,True)}</div><div class="detail-copy"><p class="eyebrow">A LITTLE CIRCLE TO MAKE YOUR OWN</p><h1>{e(d['seo'])}</h1><p class="intro">{e(d['intro'])}</p><ul class="facts"><li>Black & white line art</li><li>Large spaces for kids</li><li>Free personal & classroom use</li></ul><h2 class="download-title">Print your mandala</h2><div class="downloads"><a class="button" href="/print/{s}/">Print this mandala ↗</a></div><p class="quiet">One drawing · A4 or Letter · Portrait<br>White margins and a smaller drawing help prevent cropped edges.</p></div></section><section class="prose"><h2>Inside this little mandala</h2><p>{e(d['detail'])}</p><h2>A coloring idea to try</h2><p>{e(d['activity'])}</p><h2>Make a little moment of it</h2><p>{e(d['tip'])}</p><p>Use pencils or crayons for the smaller sections. Print on paper suited to your materials, and put a protective sheet underneath if using markers. Printing is free for home and classroom use; please link to this page when sharing the design online.</p></section><section><div class="section-heading"><h2>Another circle to explore</h2><a class="text-link" href="/coloring-pages/">See all seven mandalas ↗</a></div>{cards(related)}</section>''',[breadcrumbs,img_schema])
page('/about/','About the Studio & Patrick | Patrick’s Little Studio','Discover the ideas and creative process behind this small collection of free mandalas for kids.', '''<section class="studio about"><img src="/assets/patrick.webp" width="600" height="600" alt="Portrait of Patrick, the studio character"><div><p class="eyebrow">HELLO FROM THE STUDIO</p><h1>A little imagination,<br>on a sheet of paper.</h1><p class="intro">Patrick’s Little Studio is a small collection of playful printable mandalas for kids. Simple shapes and friendly characters are at the heart of every page.</p></div></section><section class="prose"><h2>Who is Patrick?</h2><p>Patrick is the studio’s fictional host, brought to life with an AI-created portrait. Behind the character is a real collection of printable designs, selected and prepared for coloring. </p><h2>How the drawings are made</h2><p>These designs are created with generative AI from individual creative briefs. The briefs specify circular compositions, a clear central motif, black outlines, large coloring spaces, and simpler geometric surroundings. The selected images are checked visually and prepared for direct browser printing with generous white margins.</p><h2>What makes this collection different?</h2><p>The collection starts with just seven drawings. Each has its own subject and coloring idea, without an overwhelming catalog to scroll through. The artwork stays black and white so the finished palette belongs to the child.</p><h2>For home and classroom</h2><p>Print the designs for personal activities or classroom coloring. No account is required. These are creative activities, not assessments or promises of educational or health outcomes.</p><a class="button" href="/coloring-pages/">Explore the seven mandalas ↗</a></section>''')
for path,title,description,body in PAGES:
    page(path,title,description,body,noindex=True)
page('/404/','Page Not Found | Patrick’s Little Studio','Find a printable mandala in the studio.', '<section class="page-heading"><p class="eyebrow">A LITTLE WRONG TURN</p><h1>This circle is missing.</h1><p>The page could not be found. Your next coloring page is still waiting.</p><a class="button" href="/coloring-pages/">Explore the mandalas ↗</a></section>',noindex=True)

for d in DATA:
    s=d['slug']
    dest=OUT/'print'/s/'index.html'
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><title>Print {e(d['name'])} | {brand}</title><link rel="stylesheet" href="{BASE_PATH}/assets/print.css?v=20261011"><script src="{BASE_PATH}/assets/print.js?v=20261011" defer></script></head><body><nav class="print-controls" aria-label="Print controls"><a href="{BASE_PATH}/coloring-pages/{s}/">← Back to the mandala</a><button type="button" id="print-button">Print this mandala</button><p>Choose A4 or Letter, portrait, and Fit to page. Turn off headers and footers. The drawing is reduced to 90% with extra white margins.</p></nav><main class="print-sheet"><img id="print-image" src="{BASE_PATH}/assets/{s}-print.png?v=20261023-art5" alt="{e(d['alt'])}" width="1200" height="1200"></main></body></html>''')

xml='\n'.join(f'<url><loc>{ORIGIN+p}</loc></url>' for p in pages)
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+xml+'</urlset>')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
(OUT/'_headers').write_text('/assets/*\n  Cache-Control: public, max-age=86400\n/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n')
print(f'Built {len(pages)} indexable pages, 5 noindex pages and 7 noindex print views at {ORIGIN}')
